import Foundation
import FoundationModels

// `@Generable` types the on-device model fills in. Kept small and well-described, since
// the schema itself costs context tokens. The file path is never generated by the model;
// the app attaches it.

@Generable
nonisolated enum GeneratedSeverity {
    case low, medium, high
}

@Generable
nonisolated enum GeneratedCriteriaMatch {
    case yes, partially, no, unclear
}

@Generable
nonisolated enum GeneratedConfidence {
    case low, medium, high
}

@Generable
nonisolated enum GeneratedVerdictStatus {
    case looksGood, needsHumanReview, likelyProblem
}

@Generable(description: "A specific problem in the changed lines")
nonisolated struct GeneratedConcern {
    @Guide(description: "The new line number from the diff, or a short quote of the line")
    var lineHint: String
    var severity: GeneratedSeverity
    @Guide(description: "One or two sentences on what is wrong and why")
    var explanation: String
}

@Generable(description: "Review of one changed file")
nonisolated struct GeneratedFileFinding {
    @Guide(description: "One sentence describing what the change does")
    var summary: String
    @Guide(description: "Whether this file's change satisfies the acceptance criteria; unclear if none were given")
    var meetsCriteria: GeneratedCriteriaMatch
    @Guide(description: "Real problems only; empty if the change looks correct", .maximumCount(5))
    var concerns: [GeneratedConcern]
    var confidence: GeneratedConfidence
}

@Generable(description: "Overall verdict for the merge request")
nonisolated struct GeneratedVerdict {
    var status: GeneratedVerdictStatus
    @Guide(description: "One or two sentences on how well the change covers the acceptance criteria")
    var criteriaCoverage: String
    @Guide(description: "The most important concerns, most severe first", .maximumCount(5))
    var topConcerns: [String]
    @Guide(description: "Two or three sentences explaining the verdict")
    var rationale: String
}

@Generable
nonisolated enum GeneratedDifficultyFeel {
    case simplerThanItLooks, aboutRight, harderThanItLooks
}

@Generable(description: "How hard the merge request is to review, compared with its size")
nonisolated struct GeneratedDifficulty {
    var feel: GeneratedDifficultyFeel
    @Guide(description: "One short sentence on why")
    var reason: String
}

extension GeneratedSeverity {
    nonisolated var value: Severity {
        switch self {
        case .low: .low
        case .medium: .medium
        case .high: .high
        }
    }
}

extension GeneratedCriteriaMatch {
    nonisolated var value: CriteriaMatch {
        switch self {
        case .yes: .yes
        case .partially: .partially
        case .no: .no
        case .unclear: .unclear
        }
    }
}

extension GeneratedConfidence {
    nonisolated var value: Confidence {
        switch self {
        case .low: .low
        case .medium: .medium
        case .high: .high
        }
    }
}

extension GeneratedVerdictStatus {
    nonisolated var value: VerdictStatus {
        switch self {
        case .looksGood: .looksGood
        case .needsHumanReview: .needsHumanReview
        case .likelyProblem: .likelyProblem
        }
    }
}

extension GeneratedFileFinding {
    nonisolated var result: FileReviewResult {
        FileReviewResult(
            summary: summary,
            meetsCriteria: meetsCriteria.value,
            concerns: concerns.map { ConcernResult(lineHint: $0.lineHint, severity: $0.severity.value, explanation: $0.explanation) },
            confidence: confidence.value
        )
    }
}

extension GeneratedVerdict {
    nonisolated var result: VerdictResult {
        VerdictResult(status: status.value, criteriaCoverage: criteriaCoverage, topConcerns: topConcerns, rationale: rationale)
    }
}

extension GeneratedDifficulty {
    nonisolated var result: DifficultyNudge {
        let value: DifficultyFeel = switch feel {
        case .simplerThanItLooks: .simpler
        case .aboutRight: .aboutRight
        case .harderThanItLooks: .harder
        }
        return DifficultyNudge(feel: value, reason: reason)
    }
}
